#!/usr/bin/env node
// Host-conformance fixture: issuer-key-rekeyed replay (§7.3 / §3.2 / §8).
// The verifier is spawned once per presentation. On the FIRST presentation it
// returns `allow` consuming {issuer_key:"A", nonce:N}; on the SECOND it returns
// `allow` consuming {issuer_key:"B", nonce:N} — same `nonce`, different
// `issuer_key`. §3.2 states `issuer_key` is "for host bookkeeping only; the
// `nonce` is already globally unique (§8)", so the host's unique-insert key is
// `nonce` alone and the second presentation MUST be denied as a replay. A host
// keyed on the tuple (issuer_key, nonce) reserves the second entry as novel and
// allows it — the divergence this vector catches.
//
// MAINTAINER VERIFICATION REQUIRED (rule 2k): the harness mechanism that drives
// two presentations through the host for one vector is not visible to the
// generator. This fixture assumes the same two-presentation convention used by
// host-nonce-reserve-replay-deny in spec/test-vectors.json and its fixture in
// spec/fixtures/host-conformance/. Verify (1) the `inputs` shape that vector
// uses to express the second presentation and mirror it exactly, (2) the
// `failure_class` name the host emits for a nonce-reservation conflict
// (`replay` here follows the draft pseudocode `reject("replay")`), and (3) the
// `nonce` string format the existing reserve fixtures use. Adjust this file and
// the vector entry together; none of the existing 28 vectors change.
//
// Invocation ordering is tracked in a per-run state file so the fixture stays
// deterministic and idempotent: the counter resets after the second call.
const fs = require('fs');
const os = require('os');
const path = require('path');

const STATE = path.join(
  process.env.BOLYRA_FIXTURE_STATE_DIR || os.tmpdir(),
  'bolyra-evc-replay-different-issuer-key.state'
);

// Fixed, vector-specific nonce: identical on both presentations by design.
const NONCE = 'b0f1a2c3d4e5f60718293a4b5c6d7e8f9a0b1c2d3e4f50617283940a5b6c7d8e';

function nextStep() {
  let n = 0;
  try { n = parseInt(fs.readFileSync(STATE, 'utf8'), 10) || 0; } catch (_) { n = 0; }
  const step = n + 1;
  // Reset after the second presentation so repeated suite runs start clean.
  try { fs.writeFileSync(STATE, step >= 2 ? '0' : String(step)); } catch (_) {}
  return step;
}

process.stdin.resume();
process.stdin.on('data', () => {});
process.stdin.on('end', () => {
  const step = nextStep();
  const issuer_key = step === 1 ? 'A' : 'B';
  const verdict = {
    verdict: 'allow',
    kind: 'classical',
    consume_nonces: [{ issuer_key, nonce: NONCE }]
  };
  process.stdout.write(JSON.stringify(verdict), () => process.exit(0));
});
